import { createRecord, mergeRecords, migrateLegacy } from './model.js';
const STORES = ['records', 'drafts', 'media', 'queue', 'meta'];
export class ChronicleDB {
  db; device;
  constructor(db){this.db=db;this.device=localStorage.getItem('seeker-chronicles:device-id')||crypto.randomUUID();localStorage.setItem('seeker-chronicles:device-id',this.device)}
  get(store,id){return this.read(store,'get',id)} all(store){return this.read(store,'getAll')}
  read(store,method,id){return new Promise((resolve,reject)=>{const tx=this.db.transaction(store,'readonly'),os=tx.objectStore(store),q=method==='get'?os.get(id):os.getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
  transaction(stores,action){return new Promise((resolve,reject)=>{const tx=this.db.transaction(stores,'readwrite');try{action(tx)}catch(error){tx.abort();reject(error);return}tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Сохранение прервано'))})}
  put(store,value){return this.transaction([store],tx=>{tx.objectStore(store).put(value)})} delete(store,id){return this.transaction([store],tx=>{tx.objectStore(store).delete(id)})}
  async change(type,id,fields,media=null,draftId=null){let saved;await this.transaction(['records','media','drafts'],tx=>{const records=tx.objectStore('records'),q=records.get(id);q.onsuccess=()=>{const old=q.result;saved=createRecord(type,{...old,...fields,id,version:(old?.version||0)+1,updated_at:new Date().toISOString(),device_id:this.device},this.device);records.put(saved);if(media)tx.objectStore('media').put(media);if(draftId)tx.objectStore('drafts').delete(draftId)}});return saved}
  async importRecords(incoming,media=[]){const merged=mergeRecords(await this.all('records'),incoming);await this.transaction(['records','media'],tx=>{for(const item of merged)tx.objectStore('records').put(item);for(const item of media)tx.objectStore('media').put(item)})}
}
export function openStore(scope='guest'){return new Promise((resolve,reject)=>{const q=indexedDB.open(`seeker-notebook-3:${scope}`,1);q.onupgradeneeded=()=>{for(const name of STORES)if(!q.result.objectStoreNames.contains(name))q.result.createObjectStore(name,{keyPath:'id'})};q.onsuccess=()=>resolve(new ChronicleDB(q.result));q.onerror=()=>reject(q.error);q.onblocked=()=>reject(new Error('Закройте другую вкладку журнала и повторите.'))})}
export async function migrateLocal(db){if(await db.get('meta','legacy-imported'))return;const raw=localStorage.getItem('seeker-chronicles:v2');if(raw){const records=migrateLegacy(JSON.parse(raw));if(records.length)await db.importRecords(records)}await db.put('meta',{id:'legacy-imported',at:new Date().toISOString()})}
export async function prepareImage(file){if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))throw new Error('Выберите JPEG, PNG, WebP или GIF.');if(file.size>20*1024*1024)throw new Error('Размер изображения должен быть меньше 20 МБ.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const convert=async max=>{const scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Не удалось обработать изображение')),'image/jpeg',.86))};return{id:crypto.randomUUID(),blob:await convert(1600),thumbnail:await convert(480),mime:'image/jpeg',width:image.naturalWidth,height:image.naturalHeight,upload_state:'pending'}}finally{URL.revokeObjectURL(url)}}
